<script setup lang="ts">
import { computed, ref } from 'vue';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
import { data, pendingTasks, mutate, busy, avatarStyle, dateLabel } from '../store';
const category=ref('全部'); const state=ref('待处理'); const selectedId=ref('');
const selected=computed(()=>data.tasks.find(t=>t.id===selectedId.value));
const tasks=computed(()=>data.tasks.filter(t=>(category.value==='全部'||t.category===category.value)&&(state.value==='全部'||(state.value==='已处理'?t.status!=='待处理':t.status==='待处理'))));
async function process(status:string) { if(!selected.value)return; if(await mutate(`/tasks/${selected.value.id}`,{status},'PATCH',status==='已通过'?'事项已处理':'申请已驳回'))selectedId.value=''; }
</script>
<template><div class="page-heading"><div><span class="eyebrow">MY INBOX</span><h1>待办与审批<span class="heading-count">{{ pendingTasks.length }}</span></h1><p class="page-subtitle">重要的事，有序处理。所有协作，都有回应。</p></div><div class="inbox-status"><span class="live-dot"></span>已同步最新事项</div></div><div class="inbox-layout"><aside class="panel inbox-sidebar"><p>事项分类</p><button v-for="(cat,i) in ['全部','审批','招聘','员工','绩效']" :key="cat" :class="{active:category===cat}" @click="category=cat"><Icon :name="['stack','file','briefcase','users','target'][i]" :size="19"/><span>{{ cat==='全部'?'全部待办':cat+'事项' }}</span><small>{{ pendingTasks.filter(t=>cat==='全部'||t.category===cat).length }}</small></button><div class="inbox-tip"><Icon name="insight" :size="22"/><strong>先处理紧急事项</strong><p>优先关注即将到期的审批，帮助团队顺畅协作。</p></div></aside><section class="panel inbox-main"><div class="toolbar"><div class="underlined-tabs"><button v-for="s in ['待处理','已处理','全部']" :key="s" :class="{active:state===s}" @click="state=s">{{ s }}</button></div><span class="muted">{{ tasks.length }} 项事项</span></div><button v-for="task in [...tasks].sort((a,b)=>Number(b.priority==='紧急')-Number(a.priority==='紧急'))" :key="task.id" class="inbox-task" @click="selectedId=task.id"><span class="avatar" :style="avatarStyle(task.subject)">{{ task.subject.slice(0,1) }}</span><span class="inbox-task-main"><strong>{{ task.title }}<span v-if="task.priority==='紧急'&&task.status==='待处理'" class="urgent-label">紧急</span></strong><small>{{ task.subject }} · {{ task.department }} · {{ task.category }}</small><p>{{ task.description }}</p></span><span class="inbox-task-meta"><span class="badge" :class="task.status==='待处理'?'badge-amber':task.status==='已通过'?'badge-green':'badge-red'">{{ task.status }}</span><small>{{ dateLabel(task.dueDate) }} 截止</small></span><Icon name="chevronRight" :size="18"/></button><div v-if="!tasks.length" class="empty-state inbox-empty"><span class="empty-success"><Icon name="checkCircle" :size="40"/></span><h3>{{ state==='待处理'?'待办已清空，做得很好':'暂无符合条件的事项' }}</h3><p>每一次及时回应，都在让协作更顺畅。</p></div></section></div><Modal v-if="selected" :title="selected.title" :subtitle="selected.category+'事项 · '+selected.department" @close="selectedId=''"><dl class="detail-grid"><div><dt>关联人 / 对象</dt><dd>{{ selected.subject }}</dd></div><div><dt>截止日期</dt><dd>{{ selected.dueDate }}</dd></div><div><dt>优先级</dt><dd>{{ selected.priority }}</dd></div><div><dt>处理状态</dt><dd>{{ selected.status }}</dd></div></dl><div class="request-description"><h3>事项说明</h3><p>{{ selected.description }}</p></div><p class="data-note">处理结果将记入操作审计。本版完成待办状态流转，业务系统的实际执行需后续接入。</p><template #footer><button class="btn" @click="selectedId=''">关闭</button><button v-if="selected.status==='待处理'&&selected.category==='审批'" class="btn btn-danger-text" :disabled="busy" @click="process('已驳回')">驳回申请</button><button v-if="selected.status==='待处理'" class="btn btn-primary" :disabled="busy" @click="process('已通过')"><Icon name="check" :size="17"/>{{ selected.category==='审批'?'同意申请':'确认完成' }}</button></template></Modal></template>
